fn parse_type_list(list: &str) -> std::collections::HashMap<String, Vec<String>> {
    let mut map = std::collections::HashMap::new();
    for line in list.lines() {
        if let Some(colon) = line.find(": ") {
            let name = line[..colon].to_string();
            let globs_str = &line[colon+2..];
            let globs: Vec<String> = globs_str.split(", ").map(|s| s.to_string()).collect();
            map.insert(name, globs);
        }
    }
    map
}

fn run_tui(
    regex: regex::Regex,
    pattern_original: String,
    paths: Vec<String>,
    hidden: bool,
    follow: bool,
    glob_set: Option<globset::GlobSet>,
    type_matching: Vec<String>,
    type_not: Vec<String>,
    type_map: std::collections::HashMap<String, Vec<String>>,
    theme: &str,
    context_viewer: &str,
    sort: Option<String>,
    sortr: Option<String>,
    editor_opt: Option<String>,
    custom_command_opt: Option<String>,
    multiline: bool,
    ignore_case_effective: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    use crossterm::{
        event::{self, Event, KeyCode, KeyEvent, KeyModifiers},
        execute,
        terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
    };
    use ratatui::{
        backend::CrosstermBackend,
        layout::{Constraint, Direction, Layout, Rect},
        style::{Color, Modifier, Style},
        widgets::{Block, Borders, List, ListItem, ListState, Paragraph, Clear},
        Terminal,
    };
    use std::io;

    // Setup terminal - if fails, return error that will be printed as "Error: Resource temporarily unavailable (os error 11)"
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // Channel for search results
    let (tx, rx) = mpsc::channel::<SearchMatch>();

    // Clone for thread
    let regex_clone = regex.clone();
    let paths_clone = paths.clone();
    let hidden_clone = hidden;
    let follow_clone = follow;
    let glob_set_clone = glob_set.clone();
    let type_matching_clone = type_matching.clone();
    let type_not_clone = type_not.clone();
    let type_map_clone = type_map.clone();
    let sort_clone = sort.clone();
    let sortr_clone = sortr.clone();
    let multiline_clone = multiline;

    // Spawn search thread
    thread::spawn(move || {
        // Walk files
        let mut matches = Vec::new();
        for path_str in paths_clone {
            let path = Path::new(&path_str);
            if !path.exists() {
                continue;
            }
            // If path is file, search it directly
            if path.is_file() {
                if let Some(m) = search_file(&path, &regex_clone, multiline_clone, &type_map_clone, &type_matching_clone, &type_not_clone, &glob_set_clone, hidden_clone) {
                    for mat in m {
                        let _ = tx.send(mat);
                    }
                }
            } else if path.is_dir() {
                // Walk dir
                let mut walk_builder = walkdir::WalkDir::new(path);
                if follow_clone {
                    walk_builder = walk_builder.follow_links(true);
                }
                // For hidden: if not hidden, skip hidden files
                let walker = walk_builder.into_iter().filter_entry(move |e| {
                    if !hidden_clone {
                        // Check if file name starts with .
                        if let Some(file_name) = e.file_name().to_str() {
                            if file_name.starts_with('.') && file_name != "." && file_name != ".." {
                                return false;
                            }
                        }
                        // Also check if any component is hidden?
                        // For simplicity, check path
                        let path = e.path();
                        for comp in path.components() {
                            if let Some(os_str) = comp.as_os_str().to_str() {
                                if os_str.starts_with('.') && os_str != "." && os_str != ".." {
                                    // But need to allow if root path itself is hidden and hidden flag false? We skip.
                                    return false;
                                }
                            }
                        }
                    }
                    true
                });
                for entry in walker {
                    if let Ok(entry) = entry {
                        let p = entry.path();
                        if p.is_file() {
                            // Apply type filtering and glob filtering in search_file
                            if let Some(ms) = search_file(p, &regex_clone, multiline_clone, &type_map_clone, &type_matching_clone, &type_not_clone, &glob_set_clone, hidden_clone) {
                                for mat in ms {
                                    if tx.send(mat).is_err() {
                                        return;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    });

    // State
    let mut all_matches: Vec<SearchMatch> = Vec::new();
    let mut filtered: Vec<bool> = Vec::new(); // true if filtered out
    let mut selected: usize = 0;
    let mut status = "SEARCHING".to_string();
    let mut finished = false;
    let mut keymap_popup = false;
    let mut search_popup = false;
    let mut search_input = pattern_original.clone();
    let mut search_input_cursor = search_input.len();
    let mut context_viewer = match context_viewer {
        "vertical" => ContextViewer::Vertical,
        "horizontal" => ContextViewer::Horizontal,
        _ => ContextViewer::None,
    };
    let _theme = match theme {
        "light" => Theme::Light,
        _ => Theme::Dark,
    };
    let mut context_size = 50; // percentage?
    let mut sort_by = sort.clone();
    let mut sortr_by = sortr.clone();
    let mut file_list_offset = 0;

    // For filtering
    let mut filtered_count = 0;

    // Sorting helper
    fn sort_matches(matches: &mut [SearchMatch], sort: Option<&String>, sortr: Option<&String>) {
        if let Some(s) = sort {
            match s.as_str() {
                "path" => matches.sort_by(|a,b| a.file.cmp(&b.file)),
                "modified" => matches.sort_by(|a,b| a.modified.cmp(&b.modified)),
                "created" => matches.sort_by(|a,b| a.created.cmp(&b.created)),
                "accessed" => matches.sort_by(|a,b| a.accessed.cmp(&b.accessed)),
                _ => {}
            }
        } else if let Some(s) = sortr {
            match s.as_str() {
                "path" => matches.sort_by(|a,b| b.file.cmp(&a.file)),
                "modified" => matches.sort_by(|a,b| b.modified.cmp(&a.modified)),
                "created" => matches.sort_by(|a,b| b.created.cmp(&a.created)),
                "accessed" => matches.sort_by(|a,b| b.accessed.cmp(&a.accessed)),
                _ => {}
            }
        }
    }

    // Initial sort not applied until finished? But we will apply as we receive.

    loop {
        // Collect any new matches
        while let Ok(m) = rx.try_recv() {
            all_matches.push(m);
            filtered.push(false);
        }
        // Check if channel closed and we haven't finished
        if !finished {
            // Try to see if sender disconnected
            // We can check if rx is empty and thread finished? Simplest: if try_recv fails and no more data, we will keep searching until channel closed.
            // We'll check if channel is disconnected by trying to see if all_matches length stable and no new data after some timeout? Better to use a separate flag, but we can just check if rx.try_recv returns Disconnected.
            match rx.try_recv() {
                Err(mpsc::TryRecvError::Disconnected) => {
                    finished = true;
                    status = "FINISHED".to_string();
                    // Apply final sort
                    sort_matches(&mut all_matches, sort_by.as_ref(), sortr_by.as_ref());
                    // Reset filtered etc? Keep.
                },
                Ok(m) => {
                    all_matches.push(m);
                    filtered.push(false);
                    // Also push to previous OK? We already handled first try.
                    // To avoid missing, loop again
                    while let Ok(mm) = rx.try_recv() {
                        all_matches.push(mm);
                        filtered.push(false);
                    }
                },
                Err(mpsc::TryRecvError::Empty) => {
                    // still searching
                }
            }
