        // Prepare list of visible matches (not filtered)
        let visible_indices: Vec<usize> = all_matches.iter().enumerate().filter(|(i,_)| !filtered[*i]).map(|(i,_)| i).collect();
        let total_visible = visible_indices.len();
        let total_files: usize = {
            let mut set = std::collections::HashSet::new();
            for idx in &visible_indices {
                set.insert(&all_matches[*idx].file);
            }
            set.len()
        };
        let total_matches = all_matches.len();
        // Ensure selected within bounds
        if selected >= total_visible && total_visible > 0 {
            selected = total_visible - 1;
        }
        if total_visible == 0 {
            selected = 0;
        }

        // Render
        terminal.draw(|f| {
            let area = f.area();
            // Main layout: top is list, bottom is status bar (1 line)
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints([Constraint::Min(0), Constraint::Length(1)].as_ref())
