            // Determine if context viewer active
            let (list_area, context_area) = match context_viewer {
                ContextViewer::None => (main_area, None),
                ContextViewer::Vertical => {
                    let split = Layout::default()
                        .direction(Direction::Horizontal)
                        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)].as_ref())
