                    (split[0], Some(split[1]))
                }
            };

            // Build list items grouped by file
            let mut items: Vec<ListItem> = Vec::new();
            let mut current_file = String::new();
            let mut idx_counter = 0;
            for &idx in &visible_indices {
                let m = &all_matches[idx];
                if m.file != current_file {
                    current_file = m.file.clone();
                    // file header
                    let style = if visible_indices.get(selected).map(|&s| s == idx).unwrap_or(false) {
                        // header selected? Actually selection is on match, not header. We'll style file header differently?
                        Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)
                    } else {
                        Style::default().fg(Color::Magenta).add_modifier(Modifier::BOLD)
                    };
                    items.push(ListItem::new(current_file.clone()).style(style));
                }
                // match line
                let is_selected = visible_indices.get(selected).map(|&s| s == idx).unwrap_or(false);
                let content = format!(" {}: {}", m.line_number, m.line_content);
