fn centered_rect(percent_x: u16, percent_y: u16, r: ratatui::layout::Rect) -> ratatui::layout::Rect {
    use ratatui::layout::{Constraint, Direction, Layout};
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);

    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

fn search_file(
    path: &Path,
    regex: &regex::Regex,
    multiline: bool,
    type_map: &std::collections::HashMap<String, Vec<String>>,
    type_matching: &[String],
    type_not: &[String],
    glob_set: &Option<globset::GlobSet>,
    _hidden: bool,
) -> Option<Vec<SearchMatch>> {
    // Apply glob filter
    if let Some(gs) = glob_set {
        // Check if file matches glob
        // globset matches on path
        if !gs.is_match(path) {
            // Also try file name only?
            // For simplicity, if not matched, skip
            // But ripgrep's glob includes files/directories matching glob - if any glob matches, include. So if glob_set present and not matched, skip.
            return None;
        }
    }

    // Apply type filters
    if !type_matching.is_empty() {
        // Need to check if file matches any of selected types
        let mut matched = false;
        for type_name in type_matching {
            if let Some(globs) = type_map.get(type_name) {
                for g in globs {
                    // g is like "*.rs" or "Cargo.lock"
                    // Use glob matching on file name
                    if glob_match(g, path) {
                        matched = true;
                        break;
                    }
                }
            }
            if matched { break; }
        }
        if !matched {
            return None;
        }
    }
    if !type_not.is_empty() {
        for type_name in type_not {
            if let Some(globs) = type_map.get(type_name) {
                for g in globs {
                    if glob_match(g, path) {
                        return None;
                    }
                }
            }
        }
    }

    // Read file
    // For binary detection, skip if contains null?
    let content = match std::fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => {
            // Try reading as bytes and check if binary? Skip binary files
            return None;
        }
    };

    let mut results = Vec::new();

    // Get file metadata for sorting
    let metadata = std::fs::metadata(path).ok();
    let modified = metadata.as_ref().and_then(|m| m.modified().ok());
    let created = metadata.as_ref().and_then(|m| m.created().ok());
    let accessed = metadata.as_ref().and_then(|m| m.accessed().ok());

    if multiline {
        for mat in regex.find_iter(&content) {
            // Find line number of match start
            let start = mat.start();
            let line_num = content[..start].matches('\n').count() + 1;
            // Get line content
            let line_content = content[..start].rfind('\n').map(|pos| {
                let line_start = pos+1;
                let line_end = content[line_start..].find('\n').map(|p| line_start+p).unwrap_or(content.len());
                content[line_start..line_end].to_string()
            }).unwrap_or_else(|| {
                let line_end = content.find('\n').unwrap_or(content.len());
                content[..line_end].to_string()
            });
            results.push(SearchMatch {
                file: path.to_string_lossy().to_string(),
                line_number: line_num,
                line_content,
                path: path.to_path_buf(),
                modified,
                created,
                accessed,
            });
        }
    } else {
        for (idx, line) in content.lines().enumerate() {
            if regex.is_match(line) {
                results.push(SearchMatch {
                    file: path.to_string_lossy().to_string(),
                    line_number: idx+1,
                    line_content: line.to_string(),
                    path: path.to_path_buf(),
                    modified,
                    created,
                    accessed,
                });
            }
        }
    }

    if results.is_empty() { None } else { Some(results) }
}

fn glob_match(pattern: &str, path: &Path) -> bool {
    // Use glob crate for matching file name
    // If pattern contains '/', match full path, else match file name
    if pattern.contains('/') {
        // Match full path string? Simplified
        glob::Pattern::new(pattern).map(|p| p.matches(&path.to_string_lossy())).unwrap_or(false)
    } else if pattern.contains("*.") || pattern.starts_with("*.") || pattern.contains('*') || pattern.contains('?') {
        if let Some(file_name) = path.file_name().and_then(|n| n.to_str()) {
            glob::Pattern::new(pattern).map(|p| p.matches(file_name)).unwrap_or(false)
        } else {
            false
        }
    } else {
        // Exact file name match like "Cargo.lock" or "BUILD"
        if let Some(file_name) = path.file_name().and_then(|n| n.to_str()) {
            file_name == pattern || path.to_string_lossy().ends_with(pattern)
        } else {
            false
        }
    }
}
