                Ok(m) => {
                    all_matches.push(m);
                    filtered.push(false);
                    // Also push to previous OK? We already handled first try.
                    // To avoid missing, loop again
                    while let Ok(mm) = rx.try_recv() {
                        all_matches.push(mm);
                        filtered.push(false);
                    }
                },
                Err(mpsc::TryRecvError::Empty) => {
                    // still searching
                }
            }
