fn build_cli() -> Command {
    Command::new("igrep")
        .bin_name("executable")
        .version("1.3.0")
        .about("Interactive Grep")
        .override_usage("executable [OPTIONS] --type-list <PATTERN> [PATHS]...")
        .arg(Arg::new("editor").long("editor").value_name("EDITOR").value_parser(["vim","neovim","nvim","nano","code","vscode","code-insiders","emacs","emacsclient","hx","helix","subl","sublime-text","micro","intellij","goland","pycharm","less","fresh"]).help("Text editor used to open selected match"))
        .arg(Arg::new("custom_command").long("custom-command").value_name("CUSTOM_COMMAND").env("IGREP_CUSTOM_EDITOR").help("Custom command used to open selected match. Must contain {file_name} and {line_number} tokens"))
        .arg(Arg::new("theme").long("theme").value_name("THEME").default_value("dark").value_parser(["light","dark"]).help("UI color theme"))
        .arg(Arg::new("ignore_case").short('i').long("ignore-case").action(ArgAction::SetTrue).help("Searches case insensitively"))
        .arg(Arg::new("smart_case").short('S').long("smart-case").action(ArgAction::SetTrue).help("Searches case insensitively if the pattern is all lowercase. Search case sensitively otherwise"))
        .arg(Arg::new("hidden").short('.').long("hidden").action(ArgAction::SetTrue).help("Search hidden files and directories. By default, hidden files and directories are skipped"))
        .arg(Arg::new("follow").short('L').long("follow").action(ArgAction::SetTrue).help("Follow symbolic links while traversing directories"))
        .arg(Arg::new("word_regexp").short('w').long("word-regexp").action(ArgAction::SetTrue).help("Only show matches surrounded by word boundaries"))
        .arg(Arg::new("fixed_strings").short('F').long("fixed-strings").action(ArgAction::SetTrue).help("Exact matches with no regex. Useful when searching for a string full of delimiters"))
        .arg(Arg::new("multiline").short('U').long("multiline").action(ArgAction::SetTrue).help("Search with pattern contains newline character ('\\n')"))
        .arg(Arg::new("glob").short('g').long("glob").value_name("GLOB").action(ArgAction::Append).help("Include files and directories for searching that match the given glob. Multiple globs may be provided"))
        .arg(Arg::new("type_list").long("type-list").action(ArgAction::SetTrue).conflicts_with("pattern").required_unless_present("pattern").help("Show all supported file types and their corresponding globs"))
        .arg(Arg::new("type").short('t').long("type").value_name("TYPE_MATCHING").action(ArgAction::Append).help("Only search files matching TYPE. Multiple types may be provided"))
        .arg(Arg::new("type_not").short('T').long("type-not").value_name("TYPE_NOT").action(ArgAction::Append).help("Do not search files matching TYPE-NOT. Multiple types-not may be provided"))
        .arg(Arg::new("context_viewer").long("context-viewer").value_name("CONTEXT_VIEWER").default_value("none").value_parser(["none","vertical","horizontal"]).help("Context viewer position at startup"))
        .arg(Arg::new("sort").long("sort").value_name("SORT_BY").value_parser(["path","modified","created","accessed"]).help("Sort results, see ripgrep for details"))
        .arg(Arg::new("sortr").long("sortr").value_name("SORT_BY_REVERSE").value_parser(["path","modified","created","accessed"]).help("Sort results reverse, see ripgrep for details"))
        .arg(Arg::new("pattern").value_name("PATTERN").required(true).help("Regular expression used for searching"))
        .arg(Arg::new("paths").value_name("PATHS").num_args(1..).help("Files or directories to search. Directories are searched recursively. If not specified, searching starts from current directory"))
}

fn main() {
    let mut cmd = build_cli();
    let matches = cmd.clone().get_matches();

    if matches.get_flag("type_list") {
        print!("{}", TYPE_LIST);
        return;
    }

    let pattern_str = matches.get_one::<String>("pattern").unwrap().clone();
    let paths: Vec<String> = matches.get_many::<String>("paths").map(|v| v.cloned().collect()).unwrap_or_else(|| vec![".".to_string()]);
    let hidden = matches.get_flag("hidden");
    let follow = matches.get_flag("follow");
    let ignore_case = matches.get_flag("ignore_case");
    let smart_case = matches.get_flag("smart_case");
    let word_regexp = matches.get_flag("word_regexp");
    let fixed_strings = matches.get_flag("fixed_strings");
    let multiline = matches.get_flag("multiline");
    let globs: Vec<String> = matches.get_many::<String>("glob").map(|v| v.cloned().collect()).unwrap_or_default();
    let type_matching: Vec<String> = matches.get_many::<String>("type").map(|v| v.cloned().collect()).unwrap_or_default();
    let type_not: Vec<String> = matches.get_many::<String>("type_not").map(|v| v.cloned().collect()).unwrap_or_default();
    let theme_str = matches.get_one::<String>("theme").unwrap().clone();
    let context_viewer_str = matches.get_one::<String>("context_viewer").unwrap().clone();
    let sort = matches.get_one::<String>("sort").cloned();
    let sortr = matches.get_one::<String>("sortr").cloned();
    let editor_str = matches.get_one::<String>("editor").cloned();
    let custom_command_str = matches.get_one::<String>("custom_command").cloned();

    if let Some(ref cc) = custom_command_str {
        if let Err(e) = validate_custom_command(cc) {
            eprintln!("Error: Incorrect editor command: '{}'\n\nCaused by:\n    {}", cc, e);
            std::process::exit(1);
        }
    }

    let mut regex_pattern = pattern_str.clone();
    if fixed_strings {
        regex_pattern = regex::escape(&regex_pattern);
    }
    if word_regexp {
        regex_pattern = format!(r"\b{}\b", regex_pattern);
    }

    let effective_ignore_case = if smart_case {
        let has_upper = pattern_str.chars().any(|c| c.is_uppercase());
        !has_upper
    } else {
        ignore_case
    };

    let mut regex_builder = regex::RegexBuilder::new(&regex_pattern);
    regex_builder.case_insensitive(effective_ignore_case);
    regex_builder.multi_line(!multiline);
    let regex = match regex_builder.build() {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    let mut glob_set_builder = globset::GlobSetBuilder::new();
    let mut has_glob = false;
    for g in &globs {
        has_glob = true;
        let glob = globset::Glob::new(g).unwrap_or_else(|_| {
            eprintln!("Error: Invalid glob pattern: {}", g);
            std::process::exit(1);
        });
        glob_set_builder.add(glob);
    }
    let glob_set = if has_glob { Some(glob_set_builder.build().unwrap()) } else { None };

    let type_map = parse_type_list(TYPE_LIST);

    if let Err(e) = run_tui(
        regex,
        pattern_str,
        paths,
        hidden,
        follow,
        glob_set,
        type_matching,
        type_not,
        type_map,
        &theme_str,
        &context_viewer_str,
        sort,
        sortr,
        editor_str,
        custom_command_str,
        multiline,
        effective_ignore_case,
    ) {
        // Try to produce same error as original when not tty: "Error: Resource temporarily unavailable (os error 11)"
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
}

fn parse_type_list(list: &str) -> std::collections::HashMap<String, Vec<String>> {
    let mut map = std::collections::HashMap::new();
    for line in list.lines() {
        if let Some(colon) = line.find(": ") {
            let name = line[..colon].to_string();
            let globs_str = &line[colon+2..];
            let globs: Vec<String> = globs_str.split(", ").map(|s| s.to_string()).collect();
            map.insert(name, globs);
        }
    }
    map
}

fn run_tui(
    regex: regex::Regex,
    pattern_original: String,
    paths: Vec<String>,
    hidden: bool,
    follow: bool,
    glob_set: Option<globset::GlobSet>,
    type_matching: Vec<String>,
    type_not: Vec<String>,
    type_map: std::collections::HashMap<String, Vec<String>>,
    theme: &str,
    context_viewer: &str,
    sort: Option<String>,
    sortr: Option<String>,
    editor_opt: Option<String>,
    custom_command_opt: Option<String>,
    multiline: bool,
    ignore_case_effective: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    use crossterm::{
        event::{self, Event, KeyCode, KeyModifiers},
        execute,
        terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
    };
    use ratatui::{
        backend::CrosstermBackend,
        layout::{Constraint, Direction, Layout},
        style::{Color, Modifier, Style},
        widgets::{Block, Borders, List, ListItem, Paragraph, Clear},
        Terminal,
    };
    use std::io;

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let (tx, rx) = mpsc::channel::<SearchMatch>();

    let regex_clone = regex.clone();
    let paths_clone = paths.clone();
    let glob_set_clone = glob_set.clone();
    let type_matching_clone = type_matching.clone();
    let type_not_clone = type_not.clone();
    let type_map_clone = type_map.clone();

    thread::spawn(move || {
        for path_str in paths_clone {
            let path = Path::new(&path_str);
            if !path.exists() {
                continue;
            }
            if path.is_file() {
                if let Some(m) = search_file(path, &regex_clone, multiline, &type_map_clone, &type_matching_clone, &type_not_clone, &glob_set_clone, hidden) {
                    for mat in m {
                        if tx.send(mat).is_err() { return; }
                    }
                }
            } else if path.is_dir() {
                let mut walk_builder = walkdir::WalkDir::new(path);
                if follow {
                    walk_builder = walk_builder.follow_links(true);
                }
                let walker = walk_builder.into_iter().filter_entry(move |e| {
                    if !hidden {
                        if let Some(file_name) = e.file_name().to_str() {
                            if file_name.starts_with('.') && file_name != "." && file_name != ".." {
                                return false;
                            }
                        }
                        let p = e.path();
                        for comp in p.components() {
                            if let Some(os_str) = comp.as_os_str().to_str() {
                                if os_str.starts_with('.') && os_str.len() > 1 && os_str != "." && os_str != ".." {
                                    // check if this component is hidden
                                    // Allow if it's the starting path? For simplicity, skip hidden
                                    // Need to avoid skipping the root itself if hidden and hidden flag false? But we already check file_name.
                                    // We'll check if path depth > 0 and component is hidden
                                    if p != Path::new(&path_str) {
                                        return false;
                                    }
                                }
                            }
                        }
                    }
                    true
                });
                for entry in walker {
                    if let Ok(entry) = entry {
                        let p = entry.path();
                        if p.is_file() {
                            if let Some(ms) = search_file(p, &regex_clone, multiline, &type_map_clone, &type_matching_clone, &type_not_clone, &glob_set_clone, hidden) {
                                for mat in ms {
                                    if tx.send(mat).is_err() { return; }
                                }
                            }
                        }
                    }
                }
            }
        }
    });

    let mut all_matches: Vec<SearchMatch> = Vec::new();
    let mut filtered: Vec<bool> = Vec::new();
    let mut selected: usize = 0;
    let mut status = "SEARCHING".to_string();
    let mut finished = false;
    let mut keymap_popup = false;
    let mut search_popup = false;
    let mut search_input = pattern_original.clone();
    let mut context_viewer_state = match context_viewer {
        "vertical" => ContextViewer::Vertical,
        "horizontal" => ContextViewer::Horizontal,
        _ => ContextViewer::None,
    };
    let _theme = match theme {
        "light" => Theme::Light,
        _ => Theme::Dark,
    };
    let mut _context_size: u16 = 50;
    let mut sort_by = sort.clone();
    let mut sortr_by = sortr.clone();
    let mut filtered_count: usize = 0;
    let mut last_g_pressed = false;

    fn sort_matches(matches: &mut [SearchMatch], sort: Option<&String>, sortr: Option<&String>) {
        if let Some(s) = sort {
            match s.as_str() {
                "path" => matches.sort_by(|a,b| a.file.cmp(&b.file)),
                "modified" => matches.sort_by(|a,b| a.modified.cmp(&b.modified)),
                "created" => matches.sort_by(|a,b| a.created.cmp(&b.created)),
                "accessed" => matches.sort_by(|a,b| a.accessed.cmp(&b.accessed)),
                _ => {}
            }
        } else if let Some(s) = sortr {
            match s.as_str() {
                "path" => matches.sort_by(|a,b| b.file.cmp(&a.file)),
                "modified" => matches.sort_by(|a,b| b.modified.cmp(&a.modified)),
                "created" => matches.sort_by(|a,b| b.created.cmp(&a.created)),
                "accessed" => matches.sort_by(|a,b| b.accessed.cmp(&a.accessed)),
                _ => {}
            }
        }
    }

    loop {
        // Drain channel
        loop {
            match rx.try_recv() {
                Ok(m) => {
                    all_matches.push(m);
                    filtered.push(false);
                },
                Err(mpsc::TryRecvError::Empty) => break,
                Err(mpsc::TryRecvError::Disconnected) => {
                    if !finished {
                        finished = true;
                        status = "FINISHED".to_string();
                        sort_matches(&mut all_matches, sort_by.as_ref(), sortr_by.as_ref());
                    }
                    break;
                }
            }
        }

        let visible_indices: Vec<usize> = all_matches.iter().enumerate().filter(|(i,_)| !filtered[*i]).map(|(i,_)| i).collect();
        let total_visible = visible_indices.len();
        let total_files = {
            let mut set = std::collections::HashSet::new();
            for &idx in &visible_indices {
                set.insert(all_matches[idx].file.clone());
            }
            set.len()
        };
        if selected >= total_visible && total_visible > 0 {
            selected = total_visible - 1;
        }
        if total_visible == 0 {
            selected = 0;
        }

        terminal.draw(|f| {
            let area = f.area();
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints([Constraint::Min(0), Constraint::Length(1)].as_ref())
                .split(area);
            let main_area = chunks[0];
            let status_area = chunks[1];

            let (list_area, ctx_area_opt) = match context_viewer_state {
                ContextViewer::None => (main_area, None),
                ContextViewer::Vertical => {
                    let split = Layout::default()
                        .direction(Direction::Horizontal)
                        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)].as_ref())
                        .split(main_area);
                    (split[0], Some(split[1]))
                },
                ContextViewer::Horizontal => {
                    let split = Layout::default()
                        .direction(Direction::Vertical)
                        .constraints([Constraint::Percentage(70), Constraint::Percentage(30)].as_ref())
                        .split(main_area);
                    (split[0], Some(split[1]))
                }
            };

            let mut items: Vec<ListItem> = Vec::new();
            let mut current_file = String::new();
            for &idx in &visible_indices {
                let m = &all_matches[idx];
                if m.file != current_file {
                    current_file = m.file.clone();
                    let style = Style::default().fg(Color::Magenta).add_modifier(Modifier::BOLD);
                    items.push(ListItem::new(current_file.clone()).style(style));
                }
                let is_selected = visible_indices.get(selected).map(|&s| s == idx).unwrap_or(false);
                let content = format!(" {}: {}", m.line_number, m.line_content);
                let mut style = Style::default();
                if is_selected {
                    style = style.bg(Color::DarkGray).fg(Color::White).add_modifier(Modifier::BOLD);
                }
                items.push(ListItem::new(content).style(style));
            }

            let block = Block::default().borders(Borders::ALL).border_type(ratatui::widgets::BorderType::Rounded);
            let list = List::new(items).block(block);
            f.render_widget(list, list_area);

            if let Some(ctx_area) = ctx_area_opt {
                if let Some(&sel_idx) = visible_indices.get(selected) {
                    let sel_match = &all_matches[sel_idx];
                    let file_content = std::fs::read_to_string(&sel_match.file).unwrap_or_default();
                    let block = Block::default().borders(Borders::ALL).border_type(ratatui::widgets::BorderType::Rounded);
                    let para = Paragraph::new(file_content).block(block);
                    f.render_widget(para, ctx_area);
                } else {
                    let block = Block::default().borders(Borders::ALL).border_type(ratatui::widgets::BorderType::Rounded);
                    let para = Paragraph::new("").block(block);
                    f.render_widget(para, ctx_area);
                }
            }

            let filtered_msg = if filtered_count > 0 {
                format!(" ({} filtered out)", filtered_count)
            } else {
                "".to_string()
            };
            let found_msg = if total_visible == 0 && finished {
                "No matches found.".to_string()
            } else {
                if total_files == 1 {
                    format!("Found {} matches in {} file{}.", total_visible, total_files, filtered_msg)
                } else {
                    format!("Found {} matches in {} files{}.", total_visible, total_files, filtered_msg)
                }
            };
            let left = format!("  {}   {}", status, found_msg);
            let right = if total_visible == 0 {
                format!("| {}/{} ", 0, 0)
            } else {
                format!("| {}/{} ", selected+1, total_visible)
            };
            let width = status_area.width as usize;
            let left_len = left.len();
            let right_len = right.len();
            let mut status_text = left.clone();
            if width > left_len + right_len {
                let pad = width - left_len - right_len;
                status_text.push_str(&" ".repeat(pad));
                status_text.push_str(&right);
            } else {
                status_text.push_str(&right);
            }
            let style = Style::default().bg(Color::DarkGray).fg(Color::White);
            let para = Paragraph::new(status_text).style(style);
            f.render_widget(para, status_area);

            if keymap_popup {
                let popup_area = centered_rect(70, 80, area);
                f.render_widget(Clear, popup_area);
                let block = Block::default().title(format!(" igrep {} ", env!("CARGO_PKG_VERSION"))).borders(Borders::ALL).border_type(ratatui::widgets::BorderType::Rounded);
                let lines = vec![
                    " Key(s)             │ Action",
                    " ───────────────────┼───────────────────────────────────────",
                    " q, Esc, Ctrl+c     │ Quit",
                    "",
                    " ?, F1              │ Open/close the keymap popup",
                    " Down, j            │ Scroll down in the keymap popup",
                    " Up, k              │ Scroll up in the keymap popup",
                    " Right, l           │ Scroll right in the keymap popup",
                    " Left, h            │ Scroll left in the keymap popup",
                    "",
                    " Down, j            │ Select next match",
                    " Up,k               │ Select previous match",
                    " Right, l, PageDown │ Select match in next file",
                    " Left, h, PageUp    │ Select match in previous file",
                    " gg, Home           │ Jump to the first match",
                    " Shift-g, End       │ Jump to the last match",
                    " Enter              │ Open current file",
                    " dd, Delete         │ Filter out selected match",
                    " dw                 │ Filter out all matches in current file",
                    " v                  │ Toggle vertical context viewer",
                    " s                  │ Toggle horizontal context viewer",
                    " +                  │ Increase context viewer size",
                    " -                  │ Decrease context viewer size",
                    " F5, /              │ Open search pattern popup",
                    " n                  │ Sort search results by name",
                    " m                  │ Sort search results by time modified",
                    " c                  │ Sort search results by time created",
                    " a                  │ Sort search results by time accessed",
                    "",
                    " Press any key to close…",
                    "",
                ];
                let text = lines.join("\n");
                let para = Paragraph::new(text).block(block);
                f.render_widget(para, popup_area);
            }

            if search_popup {
                let popup_area = centered_rect(60, 10, area);
                f.render_widget(Clear, popup_area);
                let block = Block::default().title(" Regex Pattern ").borders(Borders::ALL).border_type(ratatui::widgets::BorderType::Rounded);
                let para = Paragraph::new(search_input.clone()).block(block);
                f.render_widget(para, popup_area);
            }
        })?;

        if event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if search_popup {
                    match key.code {
                        KeyCode::Esc => { search_popup = false; },
                        KeyCode::Enter => { search_popup = false; },
                        KeyCode::Char(c) => { search_input.push(c); },
                        KeyCode::Backspace => { search_input.pop(); },
                        _ => {}
                    }
                    continue;
                }
                if keymap_popup {
                    keymap_popup = false;
                    continue;
                }
                match key.code {
                    KeyCode::Char('q') => break,
                    KeyCode::Esc => break,
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => break,
                    KeyCode::Char('?') => { keymap_popup = true; },
                    KeyCode::F(1) => { keymap_popup = true; },
                    KeyCode::Down | KeyCode::Char('j') => {
                        if key.code == KeyCode::Char('j') && last_g_pressed { last_g_pressed = false; }
                        if selected + 1 < visible_indices.len() { selected += 1; }
                        if let KeyCode::Char('g') = key.code { last_g_pressed = false; } else { last_g_pressed = false; }
                    },
                    KeyCode::Up | KeyCode::Char('k') => {
                        if selected > 0 { selected -= 1; }
                        last_g_pressed = false;
                    },
                    KeyCode::Right | KeyCode::Char('l') => {
                        if visible_indices.len() > 0 {
                            if let Some(&cur_idx) = visible_indices.get(selected) {
                                let cur_file = &all_matches[cur_idx].file;
                                for i in selected+1..visible_indices.len() {
                                    if let Some(&idx) = visible_indices.get(i) {
                                        if &all_matches[idx].file != cur_file {
                                            selected = i;
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                        last_g_pressed = false;
                    },
                    KeyCode::Left | KeyCode::Char('h') => {
                        if visible_indices.len() > 0 {
                            if let Some(&cur_idx) = visible_indices.get(selected) {
                                let cur_file = &all_matches[cur_idx].file;
                                for i in (0..selected).rev() {
                                    if let Some(&idx) = visible_indices.get(i) {
                                        if &all_matches[idx].file != cur_file {
                                            let target_file = all_matches[idx].file.clone();
                                            // find first of target
                                            let mut first = i;
                                            for j in (0..=i).rev() {
                                                if let Some(&idx2) = visible_indices.get(j) {
                                                    if &all_matches[idx2].file == &target_file {
                                                        first = j;
                                                    } else {
                                                        break;
                                                    }
                                                }
                                            }
                                            selected = first;
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                        last_g_pressed = false;
                    },
                    KeyCode::PageDown => {
                        if visible_indices.len() > 0 {
                            if let Some(&cur_idx) = visible_indices.get(selected) {
                                let cur_file = &all_matches[cur_idx].file;
                                for i in selected+1..visible_indices.len() {
                                    if let Some(&idx) = visible_indices.get(i) {
                                        if &all_matches[idx].file != cur_file {
                                            selected = i;
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                    },
                    KeyCode::PageUp => {
                        if visible_indices.len() > 0 {
                            if let Some(&cur_idx) = visible_indices.get(selected) {
                                let cur_file = &all_matches[cur_idx].file;
                                for i in (0..selected).rev() {
                                    if let Some(&idx) = visible_indices.get(i) {
                                        if &all_matches[idx].file != cur_file {
                                            let target_file = all_matches[idx].file.clone();
                                            let mut first = i;
                                            for j in (0..=i).rev() {
                                                if let Some(&idx2) = visible_indices.get(j) {
                                                    if &all_matches[idx2].file == &target_file {
                                                        first = j;
                                                    } else {
                                                        break;
                                                    }
                                                }
                                            }
                                            selected = first;
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                    },
                    KeyCode::Home => { selected = 0; last_g_pressed = false; },
                    KeyCode::End => {
                        if !visible_indices.is_empty() { selected = visible_indices.len()-1; }
                        last_g_pressed = false;
                    },
                    KeyCode::Char('g') => {
                        if last_g_pressed {
                            selected = 0;
                            last_g_pressed = false;
                        } else {
                            last_g_pressed = true;
                        }
                    },
                    KeyCode::Char('G') => {
                        if !visible_indices.is_empty() { selected = visible_indices.len()-1; }
                        last_g_pressed = false;
                    },
                    KeyCode::Enter => {
                        if let Some(&idx) = visible_indices.get(selected) {
                            let m = &all_matches[idx];
                            let (bin, args) = if let Some(ref cc) = custom_command_opt {
                                let cmd = cc.replace("{file_name}", &m.file).replace("{line_number}", &m.line_number.to_string());
                                let parts: Vec<String> = cmd.split_whitespace().map(|s| s.to_string()).collect();
                                if parts.is_empty() { continue; }
                                (parts[0].clone(), parts[1..].to_vec())
                            } else {
                                let editor_name = if let Some(ref ed) = editor_opt {
                                    ed.clone()
                                } else if let Ok(v) = std::env::var("IGREP_EDITOR") {
                                    v
                                } else if let Ok(v) = std::env::var("VISUAL") {
                                    v
                                } else if let Ok(v) = std::env::var("EDITOR") {
                                    v
                                } else {
                                    "vim".to_string()
                                };
                                if let Some(ed) = Editor::from_str(&editor_name) {
                                    ed.to_command(&m.file, m.line_number)
                                } else {
                                    (editor_name, vec![format!("+{}", m.line_number), m.file.clone()])
                                }
                            };
                            disable_raw_mode()?;
                            execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
                            terminal.show_cursor()?;
                            let mut cmd = std::process::Command::new(&bin);
                            cmd.args(&args);
                            let _ = cmd.status();
                            enable_raw_mode()?;
                            execute!(terminal.backend_mut(), EnterAlternateScreen)?;
                            terminal.clear()?;
                        }
                        last_g_pressed = false;
                    },
                    KeyCode::Delete => {
                        if let Some(&idx) = visible_indices.get(selected) {
                            if !filtered[idx] {
                                filtered[idx] = true;
                                filtered_count += 1;
                            }
                        }
                        last_g_pressed = false;
                    },
                    KeyCode::Char('d') => {
                        if event::poll(std::time::Duration::from_millis(300))? {
                            if let Event::Key(next) = event::read()? {
                                match next.code {
                                    KeyCode::Char('d') => {
                                        if let Some(&idx) = visible_indices.get(selected) {
                                            if !filtered[idx] {
                                                filtered[idx] = true;
                                                filtered_count += 1;
                                            }
                                        }
                                    },
                                    KeyCode::Char('w') => {
                                        if let Some(&cur_idx) = visible_indices.get(selected) {
                                            let cur_file = all_matches[cur_idx].file.clone();
                                            for (i, mm) in all_matches.iter().enumerate() {
                                                if !filtered[i] && mm.file == cur_file {
                                                    filtered[i] = true;
                                                    filtered_count += 1;
                                                }
                                            }
                                        }
                                    },
                                    _ => {}
                                }
                            }
                        }
                        last_g_pressed = false;
                    },
                    KeyCode::Char('v') => {
                        context_viewer_state = match context_viewer_state {
                            ContextViewer::Vertical => ContextViewer::None,
                            _ => ContextViewer::Vertical,
                        };
                        last_g_pressed = false;
                    },
                    KeyCode::Char('s') => {
                        context_viewer_state = match context_viewer_state {
                            ContextViewer::Horizontal => ContextViewer::None,
                            _ => ContextViewer::Horizontal,
                        };
                        last_g_pressed = false;
                    },
                    KeyCode::Char('+') => {
                        if _context_size < 90 { _context_size += 5; }
                        last_g_pressed = false;
                    },
                    KeyCode::Char('-') => {
                        if _context_size > 10 { _context_size -= 5; }
                        last_g_pressed = false;
                    },
                    KeyCode::Char('/') => { search_popup = true; search_input = pattern_original.clone(); last_g_pressed = false; },
                    KeyCode::F(5) => { search_popup = true; search_input = pattern_original.clone(); last_g_pressed = false; },
                    KeyCode::Char('n') => {
                        sort_by = Some("path".to_string());
                        sortr_by = None;
                        sort_matches(&mut all_matches, sort_by.as_ref(), sortr_by.as_ref());
                        last_g_pressed = false;
                    },
                    KeyCode::Char('m') => {
                        sort_by = Some("modified".to_string());
                        sortr_by = None;
                        sort_matches(&mut all_matches, sort_by.as_ref(), sortr_by.as_ref());
                        last_g_pressed = false;
                    },
                    KeyCode::Char('c') => {
                        sort_by = Some("created".to_string());
                        sortr_by = None;
                        sort_matches(&mut all_matches, sort_by.as_ref(), sortr_by.as_ref());
                        last_g_pressed = false;
                    },
                    KeyCode::Char('a') => {
                        sort_by = Some("accessed".to_string());
                        sortr_by = None;
                        sort_matches(&mut all_matches, sort_by.as_ref(), sortr_by.as_ref());
                        last_g_pressed = false;
                    },
                    _ => { last_g_pressed = false; }
                }
            }
        }
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    Ok(())
}

fn centered_rect(percent_x: u16, percent_y: u16, r: ratatui::layout::Rect) -> ratatui::layout::Rect {
    use ratatui::layout::{Constraint, Direction, Layout};
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);
    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

fn search_file(
    path: &Path,
    regex: &regex::Regex,
    multiline: bool,
    type_map: &std::collections::HashMap<String, Vec<String>>,
    type_matching: &[String],
    type_not: &[String],
    glob_set: &Option<globset::GlobSet>,
    _hidden: bool,
) -> Option<Vec<SearchMatch>> {
    if let Some(gs) = glob_set {
        if !gs.is_match(path) {
            // also check file name only? Globset may need full path; we already gave path.
            // If not match, skip when glob filter present.
            return None;
        }
    }
    if !type_matching.is_empty() {
        let mut matched = false;
        for type_name in type_matching {
            if let Some(globs) = type_map.get(type_name) {
                for g in globs {
                    if glob_match(g, path) {
                        matched = true;
                        break;
                    }
                }
            }
            if matched { break; }
        }
        if !matched { return None; }
    }
    if !type_not.is_empty() {
        for type_name in type_not {
            if let Some(globs) = type_map.get(type_name) {
                for g in globs {
                    if glob_match(g, path) {
                        return None;
                    }
                }
            }
        }
    }

    let content = match std::fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return None,
    };

    let mut results = Vec::new();
    let metadata = std::fs::metadata(path).ok();
    let modified = metadata.as_ref().and_then(|m| m.modified().ok());
    let created = metadata.as_ref().and_then(|m| m.created().ok());
    let accessed = metadata.as_ref().and_then(|m| m.accessed().ok());

    if multiline {
        for mat in regex.find_iter(&content) {
            let start = mat.start();
            let line_num = content[..start].matches('\n').count() + 1;
            let line_content = if let Some(pos) = content[..start].rfind('\n') {
                let line_start = pos + 1;
                let line_end = content[line_start..].find('\n').map(|p| line_start + p).unwrap_or(content.len());
                content[line_start..line_end].to_string()
            } else {
                let line_end = content.find('\n').unwrap_or(content.len());
                content[..line_end].to_string()
            };
            results.push(SearchMatch {
                file: path.to_string_lossy().to_string(),
                line_number: line_num,
                line_content,
                path: path.to_path_buf(),
                modified,
                created,
                accessed,
            });
        }
    } else {
        for (idx, line) in content.lines().enumerate() {
            if regex.is_match(line) {
                results.push(SearchMatch {
                    file: path.to_string_lossy().to_string(),
                    line_number: idx + 1,
                    line_content: line.to_string(),
                    path: path.to_path_buf(),
                    modified,
                    created,
                    accessed,
                });
            }
        }
    }

    if results.is_empty() { None } else { Some(results) }
}

fn glob_match(pattern: &str, path: &Path) -> bool {
    if let Some(file_name) = path.file_name().and_then(|n| n.to_str()) {
        if let Ok(p) = glob::Pattern::new(pattern) {
            if p.matches(file_name) {
                return true;
            }
        }
    }
    if let Ok(p) = glob::Pattern::new(pattern) {
        if p.matches(&path.to_string_lossy()) {
            return true;
        }
        // also check if pattern like "*.rs" matches "a.rs"
        // Already handled file_name case
    }
    // For patterns like "Cargo.lock" or "BUILD" exact match
    if let Some(file_name) = path.file_name().and_then(|n| n.to_str()) {
        if file_name == pattern {
            return true;
        }
    }
    // For patterns like "*Dockerfile*"
    if pattern.contains("Dockerfile") {
        if let Some(file_name) = path.file_name().and_then(|n| n.to_str()) {
            if file_name.contains("Dockerfile") {
                return true;
            }
        }
    }
    false
}
