            eprintln!("Error: Invalid glob pattern: {}", g);
            std::process::exit(1);
        });
        glob_set_builder.add(glob);
    }
    let glob_set = if has_glob { Some(glob_set_builder.build().unwrap()) } else { None };
    let type_map = parse_type_list(TYPE_LIST);

