fn centered_rect(px: u16, py: u16, r: ratatui::layout::Rect) -> ratatui::layout::Rect {
    use ratatui::layout::{Constraint, Direction, Layout};
    let v = Layout::default().direction(Direction::Vertical).constraints([Constraint::Percentage((100-py)/2), Constraint::Percentage(py), Constraint::Percentage((100-py)/2)]).split(r);
    Layout::default().direction(Direction::Horizontal).constraints([Constraint::Percentage((100-px)/2), Constraint::Percentage(px), Constraint::Percentage((100-px)/2)]).split(v[1])[1]
}
fn search_file(
    path: &Path,
    regex: &regex::Regex,
    multiline: bool,
    type_map: &std::collections::HashMap<String, Vec<String>>,
    type_matching: &[String],
    type_not: &[String],
    glob_set: &Option<globset::GlobSet>,
    _hidden: bool,
) -> Option<Vec<SearchMatch>> {
    if let Some(gs) = glob_set { if !gs.is_match(path) { return None; } }
    if !type_matching.is_empty() {
        let mut matched = false;
        for tn in type_matching {
            if let Some(globs) = type_map.get(tn) {
                for g in globs { if glob_match(g, path) { matched=true; break; } }
            }
            if matched { break; }
        }
        if !matched { return None; }
    }
    if !type_not.is_empty() {
        for tn in type_not {
            if let Some(globs) = type_map.get(tn) {
                for g in globs { if glob_match(g, path) { return None; } }
            }
        }
    }
    let content = std::fs::read_to_string(path).ok()?;
    let meta = std::fs::metadata(path).ok();
    let modified = meta.as_ref().and_then(|m| m.modified().ok());
    let created = meta.as_ref().and_then(|m| m.created().ok());
    let accessed = meta.as_ref().and_then(|m| m.accessed().ok());
    let mut res = Vec::new();
    if multiline {
        for m in regex.find_iter(&content) {
            let start = m.start();
            let line_num = content[..start].matches('\n').count()+1;
            let line_content = if let Some(pos) = content[..start].rfind('\n') {
                let ls = pos+1;
                let le = content[ls..].find('\n').map(|p| ls+p).unwrap_or(content.len());
                content[ls..le].to_string()
            } else {
                let le = content.find('\n').unwrap_or(content.len());
                content[..le].to_string()
            };
            res.push(SearchMatch { file: path.to_string_lossy().to_string(), line_number: line_num, line_content, modified, created, accessed });
        }
    } else {
        for (idx, line) in content.lines().enumerate() {
            if regex.is_match(line) {
                res.push(SearchMatch { file: path.to_string_lossy().to_string(), line_number: idx+1, line_content: line.to_string(), modified, created, accessed });
            }
        }
    }
    if res.is_empty() { None } else { Some(res) }
}
fn glob_match(pattern: &str, path: &Path) -> bool {
    if let Some(fname) = path.file_name().and_then(|n| n.to_str()) {
        if let Ok(p) = glob::Pattern::new(pattern) {
            if p.matches(fname) { return true; }
        }
        if fname == pattern { return true; }
        if pattern.contains("Dockerfile") && fname.contains("Dockerfile") { return true; }
    }
    if let Ok(p) = glob::Pattern::new(pattern) {
        if p.matches(&path.to_string_lossy()) { return true; }
    }
    false
}
